// Try both body locations - handles both raw and parsed webhook data
const body = items[0].json.body || items[0].json || {};
const client_name = body.client_name || "Unknown Client";
const category = body.category || "CRM";
const raw_requirement_text = body.raw_requirement_text || "";
const budget_range = body.budget_range || "Not specified";
const deadline_preference = body.deadline_preference || "Not specified";

const prompt = `
You are an AI Product Manager.

Generate a structured product brief for the following client request:

Client Name: ${client_name}
Category: ${category}
Requirements: ${raw_requirement_text}
Budget: ${budget_range}
Timeline: ${deadline_preference}

Return ONLY valid JSON in this exact format with NO extra text:

{
  "client_name": "${client_name}",
  "category": "string",
  "features": ["string"],
  "sub_features": ["string"],
  "description": "string"
}
`;

return [{ json: { client_name, category, raw_requirement_text, budget_range, deadline_preference, prompt } }];

const responseText = $json.choices[0].message.content;
const client_name = items[0].json.client_name || "";
let jsonStr = responseText;
jsonStr = jsonStr.replace(/```json\n?/g, '').replace(/```/g, '').trim();
const start = jsonStr.indexOf('{');
const end = jsonStr.lastIndexOf('}');
if (start !== -1 && end !== -1) {
  jsonStr = jsonStr.substring(start, end + 1);
}
let parsed;
try { parsed = JSON.parse(jsonStr); } catch (e) {
  parsed = {
    category: "CRM",
    features: ["Order Tracking","Customer Database","Reporting"],
    sub_features: ["Dashboard","Analytics","Notifications"],
    description: "AI-generated product brief"
  };
}
return [{ json: {
  client_name: parsed.client_name || client_name,
  category: parsed.category || "CRM",
  features: parsed.features || [],
  sub_features: parsed.sub_features || [],
  description: parsed.description || ""
}}];

